const body = $input.first().json.body || $input.first().json;
const entry = (body.entry || [])[0] || {};
const change = (entry.changes || [])[0] || {};
const value = change.value || {};
return [{ json: {
  comment_id: value.comment_id || '',
  message: value.message || '',
  commentateur: (value.from && value.from.name) || 'Client',
  post_id: value.post_id || entry.id || ''
} }];

const r = $input.first().json;
let texte = '';
try { texte = r.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) { texte = ''; }
if (!texte) texte = 'Merci pour votre commentaire ! Ecrivez-nous en message prive pour commander.';
return [{ json: { reponse: texte } }];
